import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';import 'package:sehatak/app_router.dart';import 'package:sehatak/core/models/women/women_models.dart';import 'package:sehatak/core/services/women_service.dart';class WomenDoctorsScreen extends StatelessWidget{const WomenDoctorsScreen({super.key});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('أطباء صحة المرأة')),body:StreamBuilder<List<WomenDoctor>>(stream:WomenService().streamDoctors(limit:20),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(padding:const EdgeInsets.all(16),children:s.data!.map((d)=>Card(child:ListTile(onTap:()=>c.push(AppRouter.womenDoctorDetail.replaceFirst(':id',d.id)),leading:CircleAvatar(backgroundImage:d.photoUrl.isNotEmpty?NetworkImage(d.photoUrl):null,child:d.photoUrl.isEmpty?const Icon(Icons.person):null),title:Text(d.name),subtitle:Text('${d.specialty} • ${d.experienceYears} سنة'),trailing:Text('★${d.rating.toStringAsFixed(1)}')))).toList());}));}}
